// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }

    // Fuzz the 'from' actor and a small array length (we will construct the array inside using the fuzzed length)
    // The property: when transfer(...) does not revert, it returns true on the reference implementation.
    // We fuzz: address fromAddr and uint8 tosCount and uint256 v. We then deploy a Recorder callee that
    // exposes the exact signature transferFrom(address,address,uint256) so c's low-level call hits it and succeeds.
    // We ensure tosCount >= 1 (require in contract) and build that many recipients. The recorder will record
    // the number of calls and the last decoded args so we observe c's external behavior via the helper.
    function testFuzz_property(address fromAddr, uint8 tosCount, uint256 v) public {
        // keep tosCount in a reasonable bound but allow 1..5 to explore loops; must be >=1 to satisfy require
        uint8 n = tosCount % 5; // 0..4
        uint8 count = n == 0 ? 1 : n; // 1..4

        // build tos array
        address[] memory tos = new address[](count);
        for (uint i = 0; i < count; i++) {
            // derive pseudo-random addresses from fromAddr and indices to keep wide
            tos[i] = address(uint160(uint256(keccak256(abi.encodePacked(fromAddr, i, block.timestamp)))));
        }

        // deploy a Recorder that implements transferFrom(address,address,uint256) and always succeeds
        Recorder rec = new Recorder();

        // Call transfer on c. We catch whether it returns or reverts; the property concerns calls that complete.
        bool ok;
        try c.transfer(fromAddr, address(rec), tos, v) returns (bool retval) {
            ok = true;
            // The reference contract is expected to return true on successful completion for ALL inputs.
            // We assert that retval is true. The mutant that returns false will make this assertion fail for some inputs.
            assertTrue(retval);
        } catch {
            // If it reverts, the property statement is vacuously satisfied (we restrict our assertion to non-reverting calls).
            ok = false;
            // nothing to assert about retval when it reverts
        }

        // Additionally, to ensure the external calls happened as expected, if the transfer completed, the recorder
        // must have observed exactly `count` calls and its recorded last-from must match the provided fromAddr.
        // We only assert these observational facts when the call did not revert (ok == true).
        if (ok) {
            // Obs: recorder exposes public getters for recordedCount and lastFrom
            // They reflect c's outward behavior; asserting them further ties observable behavior to success path.
            assertTrue(rec.recordedCount() == count);
            assertTrue(rec.lastFrom() == fromAddr);
        }
    }
}

// Recorder helper: exposes the exact signature called by c and records calls.
contract Recorder {
    uint public recordedCount;
    address public lastFrom;
    address public lastTo;
    uint public lastV;

    // must match: transferFrom(address,address,uint256)
    function transferFrom(address _from, address _to, uint256 _v) external returns (bool) {
        recordedCount += 1;
        lastFrom = _from;
        lastTo = _to;
        lastV = _v;
        return true; // succeed so reference continues
    }
}
